('esco/skill/graphql-server', 'GraphQL Server (Apollo / Yoga)', ARRAY['apollo server','graphql yoga']::text[], 'Server-side implementations of GraphQL exposing typed schemas over HTTP and WebSocket.'),
('esco/skill/vite', 'Vite', ARRAY[]::text[], 'Frontend build tool with native ESM dev server, lightning HMR, and Rollup-based production builds.'),
('esco/skill/webpack', 'Webpack', ARRAY[]::text[], 'JavaScript module bundler with loaders, plugins, code splitting, and tree shaking.'),
('esco/skill/storybook', 'Storybook', ARRAY[]::text[], 'UI component workshop for building, documenting, and visually testing components in isolation.'),
('esco/skill/zustand', 'Zustand', ARRAY[]::text[], 'Small unopinionated state-management library for React using hooks and a tiny store API.'),
('esco/skill/redux', 'Redux', ARRAY['redux toolkit']::text[], 'Predictable state container for JavaScript apps with actions, reducers, middleware, and dev tools.'),
('esco/skill/tanstack-query', 'TanStack Query', ARRAY['react query','tanstack-query']::text[], 'Async state library for fetching, caching, and synchronising server data in React, Vue, Solid, and Svelte.'),
('esco/skill/observability', 'Observability', ARRAY['monitoring','sli','slo']::text[], 'Discipline of understanding system behaviour through metrics, logs, traces, SLIs, and SLOs.'),
('esco/skill/sre', 'Site Reliability Engineering', ARRAY['sre']::text[], 'Engineering practice that applies software discipline to operations, with error budgets and toil reduction.'),
('esco/skill/load-testing', 'Load and Performance Testing', ARRAY['k6','jmeter','gatling']::text[], 'Designing and running load, stress, and soak tests using k6, JMeter, or Gatling against production-like systems.'),
('esco/skill/api-design', 'API Design (REST / GraphQL)', ARRAY[]::text[], 'Designing well-versioned, ergonomic, and consistent HTTP and GraphQL APIs with clear error semantics.'),
('esco/skill/event-driven', 'Event-Driven Architecture', ARRAY['eda']::text[], 'Architectural style where services communicate via asynchronous events on durable log/queue infrastructure.'),
('esco/skill/system-design', 'System Design', ARRAY['high-level design']::text[], 'Designing scalable, available, and maintainable distributed systems within explicit non-functional constraints.'),
('esco/skill/dsa-interview', 'Algorithmic Interview Preparation', ARRAY['leetcode','competitive programming']::text[], 'Pattern-based practice for typical software-engineering coding interviews — arrays, graphs, DP, intervals.'),
('esco/skill/agile', 'Agile / Scrum', ARRAY['scrum','kanban']::text[], 'Iterative software delivery practices using Scrum or Kanban with backlogs, sprints, retros, and reviews.'),
('esco/skill/code-review', 'Code Review', ARRAY[]::text[], 'Practice of reviewing and giving constructive feedback on pull requests for quality and consistency.'),
('esco/skill/technical-writing', 'Technical Writing', ARRAY['docs','documentation']::text[], 'Writing clear engineering docs, READMEs, design proposals, and runbooks for diverse internal audiences.'),
('esco/skill/clean-code', 'Clean Code & Refactoring', ARRAY['refactoring']::text[], 'Continuously refactoring code for readability and design without changing behaviour, guided by tests.'),
('esco/skill/domain-driven-design', 'Domain-Driven Design', ARRAY['ddd']::text[], 'Modelling complex business domains via aggregates, bounded contexts, ubiquitous language, and strategic patterns.');
